from builtins import object
from taf.ul.trs_e2e_fw.lib.ems.nom.cm_operations import CMOperations
from taf.ul.trs_e2e_fw.lib.ems.nom.nom_base import NomBase
from taf.ul.trs_e2e_fw.lib.ems.nom.alarms import Alarms
from taf.ul.trs_e2e_fw.lib.ems.nom.commissioning import Commissioning
from taf.ul.trs_e2e_fw.lib.ems.nom.swm_operations import SWMOperations
from taf.ul.trs_e2e_fw.lib.ems.nom.raccli import RacCLI
from taf.ul.trs_e2e_fw.lib.ems.nom.workflow_engine import WorkflowEngine
from taf.ul.trs_e2e_fw.lib.ems.nom.other_nom_ops import OtherNomOps
from ute_common_store.store import Store


class NomInterface(object):

    def __init__(self):
        self.store = Store()

    def setup_ems(self, **kwargs):
        """
        setup_ems
        Registers the client and returns its secret. Provides connection and authorization to NOM.

        :param str client_id: identification of the API client to be registered
        :param str username: username for the user used for identification in api gateway
        :param str password: password fot the user used for identification in api gateway
        :param str apigw_uri: url for api gateway e.g. https://apigw.srncnms0x.srnblr.nsn-rdnet.net
        :param str apigw_uri: API gateway URI
        :param str client_secret:
        :param int port:
        :param str nom_version: Default: `nomv1`. Specifies version of the NOM.
        :param bool secure:

        :return: NA
        :rtype: NA
        """
        return NomBase().setup_ems(**kwargs)

    def teardown_ems(self, **kwargs):
        """
               Deletes the client

               :param str client_id: identification of the API client to be registered
               :param str username: username for the user used for identification in api gateway
               :param str password: password fot the user used for identification in api gateway
               :param str apigw_uri: url for api gatgeway e.g. https://apigw.srncnms0x.srnblr.nsn-rdnet.net
               :return: status
               :rtype: dict
        """

        return NomBase().teardown_ems(**kwargs)

    def verify_alarm(self, **kwargs):
        """
        Fetch only_active alarms

        :param int faultid: The fault id to look for
        :param bool should_exist: If True, checks for alarm's existence
        :param int occurrences: If the alarm should exist, how many occurences are expected
        :param str dist_name: The distname of Alarm object
        :param str operator: EQ, NE, LT, GT, LTE, GTE, CONTAINS

        :return: Active alarms
        :rtype: list

        """
        return Alarms().verify_alarm(**kwargs)

    def upload_alarms(self, **kwargs):
        """
        Starts alarm upload for each of the integrated element ids.

        :param list[str] integrated_ids: list of integrated element ids
        :param int timeout: Time to wait for the response of the current operation

        :return: every dict contains operation_id, status and timestamp keys.
        :rtype: list[dict]
        """

        return Alarms().upload_alarms(**kwargs)

    def configuration_manage(self, **kwargs):
        """
        This keyword is used to perform configuration management.

        :param str operation: Create or Edit or Delete
        :param str plan_name: Configuration name
        :param str description: Plan description
        :param str plan_type: Type of the configuration: ACTUAL, REFERENCE, PLAN
        :param str config: JSON file with list of dict. Either config file or moc_and_params_dict are mandatory
        :param int conf_id: An integer which identifies a configuration value.
        :param bool rollback_plan_generation: If set to true a backup plan will be auto-generated, which will be
                                              reverting changes done by the plan to their present actual values.
        :param int timeout: Time to wait for the response of the current operation
        :param bool delete_plan: Deletes plan at the end of operation
        :param bool should_provision: If True provisions the configuration after plan creation
        :param str before: Only plans whose managed objects are older than given timestamp are to be removed by this
            execution

        :return: NA
        :rtype: NA

        """
        return Commissioning().configuration_manage(**kwargs)

    def provision_plan(self, **kwargs):
        """
        Initiate plan provisioning for given plan content.
        It is expected that plan will contain only NE3S capable integrated elements.

        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param bool rollback_plan_generation: If set to true a backup plan will be auto-generated, which will be
                                              reverting changes done by the plan to their present actual values.
        :param int timeout: Time to wait for the response of the current operation

        :return list[dict]: every dict contains operation_id, status and timestamp keys.
                            Example the same as for get_operation_status.
        :rtype: NA

        """
        return Commissioning().provision_plan(**kwargs)

    def configuration_get(self, **kwargs):
        """
        Retrieves the managed objects within the given configuration which are identified by the given
        distinguished names. If the managed object for a given DN doesn't exist then there will be
        no corresponding entry in the result (doesn't represent an error).

        :param int conf_id: An integer which identifies a configuration
                                value 1 represents the actual configuration
                                value 5 represents the reference configuration
                                other values (returned when creating an empty plan) identify a plan
        :param list[str] mo_ids: A list of managed object ids

        :return: Managed object parameters
        {
          "result": [
            {
              "mo_id": "MRBTS-1234",
              "mo_class": {
                "id": "com.nokia.srbts:MRBTS",
                "version": "SBTS20C_2006_001"
              },
              "operation": None,
              "parameters": {
                "btsName": "some value"
              }
            }
          ]
        }
        :rtype: dict
        """
        return Commissioning().configuration_get(**kwargs)

    def software_manage(self, **kwargs):
        """
        Manages SW operations like Download, Activate, Provision

        :param str operation: Download or Activate or Provision
        :param str package: Build name
        :param str version_number: Example SBTS22R2. For Trunk builds(i.e.,SBTS00_ENB_9999) package name and version ID
        :param str wft_profile: Profile name from wft_filters.json
        :param str was_ssh_alias: Name of SSH Execution Context
        :param str provision_param: provision profile name in sw_provision section of testline_config
        :param list[str] integrated_ids: List of integrated network elements, e.g. ['MRBTS-1234']
        :param int timeout: Timeout for SW provision, download or activation operation.
        :param bool run_async: If set to True keyword will not wait for operation result and return operation_id
            instead.
        :param str precheck: Specifies software pre-check type before download, activate, or provision.
            Allowed values: ``fullCheck``, ``upgradeCheck`` or ``rebootCheck``.
        :param bool postcheck: Specifies whether software post-check is required after download, activate, or provision.


        :return list[dict]: every dict contains operation_id, status and timestamp keys.
                            Example the same as for get_operation_status.
                dict: containing operation_id
        {
             "operation_id": "f0d454ed-7fed-4838-ab5e-647af65b127f"
        }
        :rtype: NA

        """
        return SWMOperations().software_manage(**kwargs)

    def export(self, **kwargs):
        """
        Export entire current configuration.

        :param str file_name: Exported file name
        :param str dist_names: The scope of the export

        :return RAML2 file
        :rtype: dict
        """

        return CMOperations().export(**kwargs)

    def import_(self, **kwargs):
        """
        Import configuration plan in RAML2 format in NOM. Upon successful import, the plan with given name will be
        generally available for use in other NOM functionalities

        :param str input_file: full file path. Either this or the fileName arg are mandatory.
        :param str plan_name: "plan_name" will be chosen to select parameters from "import_" section of testline_config
        :param str description: User can optionally provide a description for content and/or purpose of this plan.
        :param bool overwrite: By default importing plan with name already existing in NOM will be refused.
        :param str plan_type: This parameter is indicating what is the type of the plan. Plan type is used to
                differenciate plans for different use cases in NOM UI. By default the user is not expected to provide
                any information for this parameter.

        :return: NA
        :rtype: NA

        """

        return RacCLI().import_(**kwargs)

    def plan(self, **kwargs):
        """
        create_empty_plan:
        Creates an empty plan with the specified header information (name and description).

        :param str operation: Create or Get or Delete
        :param str plan_name: Configuration name
        :param str description: Plan description
        :param str plan_type: Type of the configuration: ACTUAL, REFERENCE, PLAN
        :param bool ignore_errors: Ignores Errors if True(relevant for plan_type sitetemplate)
        :param int timeout: Timeout
        :param str before: Only plans whose managed objects are older than given timestamp are to be removed by this
            execution.

        :return: plan header information
        {
            "info": {
                "conf_id": 1,
                "name": "Plan Name",
                 "description": "Desc"
                    }
            }
        :rtype: dict

        """
        operation = kwargs.get('operation')
        plan_type = kwargs.get('plan_type', 'plan')
        if operation.lower() == 'delete' and plan_type.lower() == 'sitetemplate':
            return RacCLI().plan_delete(**kwargs)
        else:
            return Commissioning().plan(**kwargs)

    def apply_site_template(self, **kwargs):
        """
        Depending on boolean flags used, this operation applies templates, performs offline validation, and activates
        configuration which will then be used for NE identification during autoconnection and provisioned
        during autoconfiguration phase.

        Once the operation is finished successfully, Plug and Play process can be triggered from Network Element.

        :param str plan_name: List of integrated element ids
        :param bool apply_templates: If set to true, complement plan operation will be performed.
        :param bool validate: If set to true, offline plan validation will be performed.
        :param int timeout: Time to wait for the response of the current operation

        Optional parameters:
        :param bool overwrite: Users can optionally specify if already activated configuration should be overwritten.
                               If not provided, the operation will fail for already activated configurations.
        :param str private_key: This is a private key in PEM format.
                               If provided, the operation will use it to decrypt all OAM link password attributes stored
                               as parameters in the planned managed objects. If provided, the operation expects all such
                               attributes to be encrypted with the RSA algorithm base64 form.
                               All the new line characters in .pem content should be converted to "\n" and then
                               concatenate all the PEM lines as one long string.
                               The following command can be used for the conversion:
                                awk 'NF {sub(/\r/, ""); printf "%s\n",$0;}' pem-certificate-name.pem
                               If provided with empty value, the operation will fail.
                               If not provided, the operation expects all such parameters to be in plain text form.
        :param str user_defined_name: User can provide own name for this operation execution.
        :param str user_defined_description: User can provide with own description about this operation execution.
        :param bool deploy_cnf: If set to True, deploy-planned-cnfs operation will be performed.

        :return: every dict contains operation_id, status and timestamp keys.
                            Example the same as for get_operation_status.
        :rtype: list[dict]
        """

        return WorkflowEngine().apply_site_template(**kwargs)

    def cancel_alarms(self, **kwargs):
        """
        Cancel alarm

        :param str alarm_dn: Distinguished name of the alarm
        :param str system_alarm_id: System alarm identifier of the alarm

        :return: dict
        :rtype: dict
        """

        return Alarms().cancel_alarms(**kwargs)

    def rollback_sw(self, **kwargs):
        """
        Rollback software for given network elements.

        :param list[str] integrated_ids: List of integrated network elements, e.g. ['MRBTS-1234']
        :param Union[int,str] timeout: Timeout for SW rollback operation.

        :return: every dict contains operation_id, status and timestamp keys.
        :rtype: dict
        """
        return SWMOperations().rollback_sw(**kwargs)

    def delete_object_from_monitor(self, **kwargs):
        """
        Remove managed objects from a given configuration.

        Remove one or more managed object parameters from a given configuration.
        An error is returned if the given managed object does not exist.
        Currently, this method supports updating "PLAN" configurations only.
        For "PLAN" configurations, the removal of managed objects means that the objects are no longer part of the plan.

        :param int conf_id: PLAN type configuration id.
        :param list[str] dist_names: E.g., ["MRBTS-1234/NRBTS-4/NRCELL-1", "MRBTS-1234/NRBTS-4/NRCELL-2"]

        :return: dict
        :rtype: dict

        """
        return OtherNomOps().delete_object_from_monitor(**kwargs)

    def enb_configuration_should_be_discovered(self, **kwargs):
        """
        Integrate network elements defined in a given plan.

        This operation will process all managed objects in the plan and trigger NE-NOM integration sequences for all of
        them in parallel. Supported are only managed object classes from com.nokia.nms.integration adaptation. All other
        objects will be ignored.
        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param bool reintegrate: If set to true, Reintegrate in case the NE is already integrated to NOM.
        :param int timeout: Time to wait for the response of the current operation

        :return: list(dict)
        :rtype: list
        """
        return WorkflowEngine().integrate_ne(**kwargs)
